UPDATE businesses SET description = 'BietjiePlaas is a self-catering guest accommodation set in Kameeldrift East, Pretoria, close to the Roodeplaat Dam. The property offers several self-catering units, each able to sleep up to four guests, with secure parking provided for one vehicle per suite. Inside, each unit is equipped with a kitchenette for preparing meals, a television with DStv, and free Wi-Fi, while a braai area gives guests the option of cooking outdoors. The accommodation suits both leisure travellers and business visitors needing a self-contained base near the dam rather than a full-service hotel. With its combination of private cooking facilities, secure parking and proximity to Roodeplaat Dam, BietjiePlaas offers a self-catering alternative for visitors wanting more independence than a standard guesthouse room during their stay in the area.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.sa-venues.com/visit/bietjieplaas/'), description_enriched_at = datetime('now') WHERE slug = 'bietjieplaas-kameeldrift-east' AND description = 'BietjiePlaas is a guest house in Kameeldrift East near the Roodeplaat Dam, offering self-catering units with braai facilities and secure covered parking, about 20 minutes from Wonderboom Airport.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
